), current_max as (
  select coalesce(max("ID"), 0)::bigint as id from public."modul2_bank_menu"
), candidates as (
  select current_max.id + import_rows.source_no as "ID", import_rows.*
  from import_rows cross join current_max
  where not exists (
    select 1 from public."modul2_bank_menu" existing
    where existing."Kategori" = import_rows.kategori
      and existing."Hari" = import_rows.hari
      and existing."Nama Menu" = import_rows.menu_name
      and existing."Karbohidrat" = import_rows.karbohidrat
      and existing."Protein Hewani" = import_rows.protein_hewani
      and existing."Protein Nabati" = import_rows.protein_nabati
      and existing."Sayuran" = import_rows.sayuran
      and existing."Buah" = import_rows.buah
  )
), inserted as (
  insert into public."modul2_bank_menu" ("ID", "Nama Menu", "Hari", "Kategori", "Daerah", "Karbohidrat", "Protein Hewani", "Protein Nabati", "Sayuran", "Buah", "Kalori", "Protein", "Lemak", "AKG Data")
  select "ID", menu_name, hari, kategori, daerah, karbohidrat, protein_hewani, protein_nabati, sayuran, buah, kalori::numeric, protein::numeric, lemak::numeric, akg_data
  from candidates
  on conflict ("ID") do nothing
  returning "ID"
)
select count(*) as rows_inserted from inserted;
notify pgrst, 'reload schema';
commit;
